package com.bitewise.controller;
import com.bitewise.dto.SalesDtos.*; import com.bitewise.service.SalesService; import jakarta.validation.Valid; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/sales") public class SalesController {private final SalesService s; public SalesController(SalesService s){this.s=s;} @GetMapping("/daily") public DailySaleResponse get(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date){return s.get(date);} @PostMapping("/daily") public DailySaleResponse save(@Valid @RequestBody DailySaleRequest r){return s.save(r);} @PostMapping("/daily/{date}/close") public DailySaleResponse close(@PathVariable @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date){return s.close(date);} }
